MAX_BAD_FRACTION = 0.01  # above this share of unreadable lines, refuse to decide


def accounts_to_lock(lines, threshold=3, locked=None):
    """Return accounts with at least `threshold` failed sign-ins in this batch.

    Accounts already in `locked` are not reported again, and the caller's
    `locked` is never changed. Unreadable lines are logged with their line
    number; if more than MAX_BAD_FRACTION of the batch is unreadable the
    batch is refused with ValueError instead of being judged on partial data.
    """
    already = set(locked or ())
    failures = {}
    total = bad = 0
    for number, line in enumerate(lines, start=1):
        total += 1
        try:
            _, user, outcome = parse_line(line)
        except ValueError:
            bad += 1
            log.warning("line %d is not 'stamp,user,outcome': %r", number, line[:60])
            continue
        if outcome == "FAIL":
            failures[user] = failures.get(user, 0) + 1

    if total and bad / total > MAX_BAD_FRACTION:
        raise ValueError(f"{bad} of {total} log lines could not be read")

    to_lock = []
    for user, count in failures.items():
        if count >= threshold and user not in already:
            log.info("locking %s", user)
            to_lock.append(user)
    return to_lock

